import{_ as e,o as a,c as o,a2 as d}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"搜索语法","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/search-syntax.md","filePath":"zh-CN/user-guide/search-syntax.md","lastUpdated":1784719436000}'),s={name:"zh-CN/user-guide/search-syntax.md"};function c(r,t,i,n,l,p){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="搜索语法" tabindex="-1">搜索语法 <a class="header-anchor" href="#搜索语法" aria-label="Permalink to &quot;搜索语法&quot;">​</a></h1><p>SwiftList 的搜索框支持的不只是普通输入。下面每一种操作符都可以和普通模糊词混合使用在同一条查询里。</p><h2 id="模糊匹配-默认" tabindex="-1">模糊匹配(默认) <a class="header-anchor" href="#模糊匹配-默认" aria-label="Permalink to &quot;模糊匹配(默认)&quot;">​</a></h2><p>输入名称的任意一部分即可命中，只要字符按顺序出现在文件/文件夹名的任意位置即可，不需要输入连续的 子串：</p><table tabindex="0"><thead><tr><th>输入</th><th>命中</th></tr></thead><tbody><tr><td><code>swlst</code></td><td><code>SwiftList.exe</code></td></tr><tr><td><code>report</code></td><td><code>Q3-report-final.docx</code></td></tr></tbody></table><h2 id="多个词" tabindex="-1">多个词 <a class="header-anchor" href="#多个词" aria-label="Permalink to &quot;多个词&quot;">​</a></h2><p>用空格分隔多个词。每个词都会进一步缩小结果范围——但<strong>不要求</strong>这些词按你输入的顺序出现：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report final</span></span></code></pre></div><p><code>final-Q3-report.docx</code> 和 <code>Q3-report-final.docx</code> 都能匹配。</p><h2 id="大小写敏感" tabindex="-1">大小写敏感 <a class="header-anchor" href="#大小写敏感" aria-label="Permalink to &quot;大小写敏感&quot;">​</a></h2><ul><li><strong>全部小写</strong>的查询不区分大小写：<code>myfile</code> 可以匹配 <code>MyFile</code>、<code>MYFILE</code> 等。</li><li>只要查询里<strong>出现任意大写字母</strong>，该词就变为大小写敏感：<code>MyFile</code> 只匹配 <code>MyFile</code>，不匹配 <code>myfile</code>。</li></ul><h2 id="操作符" tabindex="-1">操作符 <a class="header-anchor" href="#操作符" aria-label="Permalink to &quot;操作符&quot;">​</a></h2><table tabindex="0"><thead><tr><th>前缀/后缀</th><th>示例</th><th>效果</th></tr></thead><tbody><tr><td>(无)</td><td><code>report</code></td><td>默认的模糊匹配，命中名称中任意位置。</td></tr><tr><td><code>!</code></td><td><code>!temp</code></td><td><strong>排除</strong>——过滤掉命中 <code>temp</code> 的结果。</td></tr><tr><td><code>&#39;</code></td><td><code>&#39;report</code></td><td><strong>精确</strong>子串匹配，替代模糊匹配。</td></tr><tr><td><code>&#39;...&#39;</code></td><td><code>&#39;final report&#39;</code></td><td>精确匹配，且要求词边界(不会命中被包在更长单词内部的情况)。</td></tr><tr><td><code>^</code></td><td><code>^IMG</code></td><td><strong>前缀</strong>匹配——名称必须以 <code>IMG</code> 开头。</td></tr><tr><td><code>$</code></td><td><code>.pdf$</code></td><td><strong>后缀</strong>匹配——名称必须以 <code>.pdf</code> 结尾。</td></tr><tr><td><code>|</code></td><td><code>report | summary</code></td><td><strong>或</strong>——匹配管道符任意一侧。</td></tr></tbody></table><p>这些操作符可以自由组合，例如 <code>^IMG !.png$ 2024</code> 可以找到以 <code>IMG</code> 开头、包含 2024、但<strong>不是</strong> PNG 的文件。</p><h2 id="指定盘符" tabindex="-1">指定盘符 <a class="header-anchor" href="#指定盘符" aria-label="Permalink to &quot;指定盘符&quot;">​</a></h2><p>在查询开头输入盘符加冒号，即可把搜索范围限定在该盘，后面照常输入关键词：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d: report</span></span></code></pre></div><p>只在 <code>D:</code> 盘搜索。</p><h2 id="路径模式" tabindex="-1">路径模式 <a class="header-anchor" href="#路径模式" aria-label="Permalink to &quot;路径模式&quot;">​</a></h2><p>如果查询里包含路径分隔符(<code>\\</code> 或 <code>/</code>)，SwiftList 会切换到路径模式，按完整路径而不仅仅是名称来匹 配——适合直接跳转到已知的文件夹：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>D:\\Projects\\SwiftList</span></span></code></pre></div><p>以分隔符结尾(<code>D:\\Projects\\</code>)则会搜索该文件夹<strong>内部</strong>的内容。</p><h2 id="按文件夹名过滤" tabindex="-1">按文件夹名过滤 <a class="header-anchor" href="#按文件夹名过滤" aria-label="Permalink to &quot;按文件夹名过滤&quot;">​</a></h2><p>在查询末尾加上 <code>::&lt;文字&gt;</code>，可以额外要求命中结果自身的名字或其某一层上级文件夹匹配 <code>&lt;文字&gt;</code>(模 糊匹配，包括拼音，跟其他地方的匹配方式完全一致)：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1080 ::wallpapers</span></span></code></pre></div><p>可以找到名字里带 <code>1080</code>、且位于某个匹配 <code>wallpapers</code> 的文件夹下面的文件，不需要知道或输入完整路 径。多个过滤条件可以用逗号组合：<code>report ::2024,:final</code>。</p><h2 id="单次搜索绕过排除规则" tabindex="-1">单次搜索绕过排除规则 <a class="header-anchor" href="#单次搜索绕过排除规则" aria-label="Permalink to &quot;单次搜索绕过排除规则&quot;">​</a></h2><p>在查询开头加 <code>*</code>，可以让这一次搜索绕过你自己设置的<a href="./settings/index-drives.html#排除规则">排除规则</a>—— <code>ExcludedPaths</code>、忽略的 glob、忽略的正则——而不需要改动设置本身：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*node_modules</span></span></code></pre></div><p><code>*</code> 本身会在匹配之前被剥离掉，不会被当成搜索文字的一部分。这只能找回<strong>已经被索引过</strong>的结果；一 个从未被索引过的文件夹(网络盘或 WSL 上被排除的文件夹)依然不会出现。隐藏/系统文件不受影响，始 终照常过滤——<code>*</code> 只影响你自己配置的排除规则。只打 <code>*</code>、后面还没打内容时，会显示&quot;继续输入以搜 索&quot;这样的提示，而不是&quot;无搜索结果&quot;，因为这时候实际上还没有真正搜索过。</p><h2 id="结果类型触发符" tabindex="-1">结果类型触发符 <a class="header-anchor" href="#结果类型触发符" aria-label="Permalink to &quot;结果类型触发符&quot;">​</a></h2><p>可选功能，默认没有配置，需要自己指定字符。如果你在<strong>设置 → 通用 → 快速搜索窗口 → 结果类型优先 级</strong>里给某个结果类型配了触发符，把这个字符打 在快速窗口查询的最前面，就只会显示这个类型的结果——应用程序、系统设置、某一个具体的文件过滤器、 某个插件自己的条目，或者纯文件——其他类型全部隐藏：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>;vs</span></span></code></pre></div><p>如果 <code>;</code> 是应用程序这个类型配置的触发符，这样搜就只会在应用程序里找&quot;Visual Studio&quot;，不管其他类 型的文本本来匹配得多好都不参与竞争。只打触发符、后面还没打内容时，会显示一个说明具体类型的提示， 而不是&quot;无搜索结果&quot;。历史记录和收藏夹不受影响——不管有没有触发符，它们始终排最前。默认没有配置任 何触发符，去<a href="./settings/general.html#快速搜索窗口">通用设置</a>里可以自行设置。</p><h2 id="中文文件名-拼音别名" tabindex="-1">中文文件名:拼音别名 <a class="header-anchor" href="#中文文件名-拼音别名" aria-label="Permalink to &quot;中文文件名:拼音别名&quot;">​</a></h2><p>包含中文字符的文件名会自动支持拼音搜索，无需任何配置：</p><ul><li><strong>全拼</strong>:输入 <code>chongqing</code> 可以匹配名为&quot;重庆&quot;的文件。</li><li><strong>首字母</strong>:输入 <code>cq</code> 同样可以匹配&quot;重庆&quot;(每个音节的首字母)。</li><li><strong>多音字</strong>(有多种读音的汉字)会为每种常见读音都生成别名，所以不管你想到的是哪种读音，通常都能 命中。</li></ul><p>这是由内置的别名插件负责实现的——如果想确认它是否启用，可以到<strong>设置 → 插件</strong>里查看。</p><h2 id="收藏夹-而非自定义别名" tabindex="-1">收藏夹，而非自定义别名 <a class="header-anchor" href="#收藏夹-而非自定义别名" aria-label="Permalink to &quot;收藏夹，而非自定义别名&quot;">​</a></h2><p>SwiftList 没有一个通用的&quot;自定义别名/宏&quot;系统。最接近的等价功能是 <a href="./settings/favorites.html">收藏夹</a>：把文件夹、文件或网址收藏为一个自定义显示名，之后就能用这个名字 搜到它(结果里会带 ★ 标记)。如果你想要的其实是&quot;自定义一个关键词来启动某个程序&quot;，可以看看 <a href="./instant-answers.html#自定义命令">自定义命令</a>。</p>',40)])])}const g=e(s,[["render",c]]);export{u as __pageData,g as default};
